interface ShipHost {
  ctx: WorldContext;
  spec(): HouseSpec;
  state(): HauntState;
  say(text: string): void;
  configure(options: StationOptions): void;
  start(): void;
  test(): void;
  stations?(): void;
  door(id: string): void;
  doorOpen?(id: string): boolean;
  doorLocked?(id: string): boolean;
  /**
   * **Ein Ding beim Kern als benutzbar anmelden** (`core/usable.ts`,
   * `PortalWorld.addUsable`): Was hier `bind` bekommt — Kistenklappen,
   * Konsolen, Tastenfelder, Türtafeln, das liegende Teil, die schwebende
   * Lampe —, bekommt damit auch `A` (am Schreibtisch `E`), den Saum und den
   * Hinweis über der Figur. Der Zeiger bleibt daneben für Hand, Trigger und
   * den Strahl aus den Augen.
   */
  usable?(object: THREE.Object3D, usable: Usable, options?: { radius?: number }): void;
  unusable?(object: THREE.Object3D): void;
  /** Versetzt den Spieler; mit `yaw` schaut er danach dorthin (`movePlayerTo`). */
  travel(at: THREE.Vector3, yaw?: number): void;
  /** Wo der Techniker aus Zahlen steht — `null`, solange keine Bot-Runde läuft (`flatKernel.ts`). */
  botPose?(): { x: number; z: number; yaw: number } | null;
  /** Was er gerade tut, für die Tafel: `cargo`, `console`, `home`, `flee`, `hide`. */
  botStage?(): string;
  /** Die Gewichte beider Bots und ihr Zeitraffer — nur in der Bot-Runde. */
  tuning?(): BotTuning;
  retune?(tuning: BotTuning): void;
  /** Ob die Grundriss-Vorlage am Boden liegt (`world3d/blueprint.ts`). */
  blueprint?(): boolean;
  setBlueprint?(on: boolean): void;
  simulationSpeed?(): number;
  /** Die Stufe direkt einstellen (`simulationSpeed.ts` rastet sie ein). */
  setSimulationSpeed?(speed: number): void;
  /** Wie das Deck in der Bot-Runde ausgeleuchtet ist. */
  lighting?(): BotLighting;
  setLighting?(lighting: Partial<BotLighting>): void;
  equip?(id: 'flashlight' | 'xray' | 'radar' | 'off', hand: Handedness): void;
  carried?(hand: Handedness): Tool | null;
  floatingTorch?(): FlashlightTool | null;
  takeFloatingTorch?(): void;
  /** Der Stand als Karte und der Gang des Monsters — für das Hörmodell (`audio/`). */
  mapSnapshot?(): MapSnapshot;
  /** Die Ziele des Technikers, das nächste zuerst — für den Kompass am oberen Bildrand. */
  objectives?(): MapGoal[];
  monsterPace?(): MonsterPace;
  /** Sauerstoff, Anzug-Leben und Kabinen der laufenden Runde (`rules/`). */
  round?(): MapRound | null;
  /** Ein Geräusch des Spielers für die Ohren des Monsters (`audio/cues.ts`, `NOISE`). */
  noise?(at: { x: number; z: number }, loudness: number): void;
}
